async function track(table: keyof typeof made, row: Record<string, unknown>) {
  const id = await insertRow(ds.manager, table, row)
  made[table].push(id)
  return id
}

/** A dept under `parent` (null = top level); tree_path = the parent's + its own id. */
async function dept(name: string, parent: string | null) {
  d[name] = await track('iam_dept', {
    parent_id: parent ? d[parent] : 0,
    name: PREFIX + name,
    tree_path: '/',
  })
  const [row] = await ds.query<{ path: string }[]>(
    'SELECT tree_path AS path FROM iam_dept WHERE id = ? AND deleted_at IS NULL',
    [parent ? d[parent] : 0],
  )
  await ds.query('UPDATE iam_dept SET tree_path = ? WHERE id = ?', [
    `${row?.path ?? '/'}${d[name]}/`,
    d[name],
  ])
}

async function user(name: Exclude<Who, 'admin'>, dept: number, roles: number[]) {
  u[name] = await track('iam_user', {
    username: PREFIX + name,
    display_name: name,
    dept_id: dept,
    password_hash: 'not-used-by-this-spec',
    password_changed_at: new Date(),
  })
  for (const r of roles)
    await ds.query('INSERT INTO iam_user_roles (user_id, role_id) VALUES (?, ?)', [u[name], r])
  tokens[name] = (await signIn(app, PREFIX + name)).accessToken
}

