describe('submit', () => {
  it('saves the request as the caller’s and starts process leave on it; days pick the path', async () => {
    const res = await submit('alice', body(3)).expect(201)
    const row = res.body.data
    expect(row).toMatchObject({
      ...body(3, { reason: row.reason }),
      userId: u.alice,
      deptId: d.sub,
      state: 'in_review',
      instanceId: expect.any(Number),
      createdBy: u.alice,
    })
    expect(await instanceRow(row.instanceId)).toEqual({
      business_key: String(row.id),
      initiator_id: u.alice,
      initiator_dept_id: d.sub,
      state: 'running',
      form_values: { days: 3, leaveKind: 'annual', startAt: '2026-10-08T01:00:00.000Z' },
    })
    expect(await openTasks(row.instanceId)).toEqual([{ node_id: 'long', assignee_id: u.carol }])
    const short = await add('alice', 1.5)
    expect(await openTasks(short.instanceId)).toEqual([{ node_id: 'short', assignee_id: u.bob }])
  })

  it('server fields in the body are ignored: the row is the caller’s, in review on its own instance', async () => {
    const forged = { userId: u.bob, deptId: d.other, state: 'approved', instanceId: MISSING }
    const row = (await submit('alice', body(3, forged)).expect(201)).body.data
    expect(row).toMatchObject({ userId: u.alice, deptId: d.sub, state: 'in_review' })
    expect(row.instanceId).not.toBe(MISSING)
    expect(await leaveRow(row.id)).toMatchObject({
      user_id: u.alice,
      dept_id: d.sub,
      state: 'in_review',
      instance_id: row.instanceId,
    })
    expect(await instanceRow(row.instanceId)).toMatchObject({
      business_key: String(row.id),
      initiator_id: u.alice,
    })
  })

  it('a start that fails keeps no row: one transaction', async () => {
    await ds.query('UPDATE wf_model SET enabled = 0 WHERE id = ?', [modelId])
    try {
      const tag = body(3)
      await submit('alice', tag).expect(404)
      const rows = await ds.query('SELECT id FROM biz_leave_request WHERE reason = ?', [tag.reason])
      expect(rows).toEqual([])
    } finally {
      await ds.query('UPDATE wf_model SET enabled = 1 WHERE id = ?', [modelId])
    }
  })

  it('400: a field missing, zero or negative days, a bad date (translated)', async () => {
    const { leaveKind: _, ...left } = body()
    const res = await submit('alice', left).set('Accept-Language', 'en-US').expect(400)
    expect(res.body.errors).toEqual([
      { path: 'leaveKind', msg: expect.stringMatching(/Leave type/) },
    ])
    for (const days of [0, -1]) await submit('alice', body(days)).expect(400)
    await submit('alice', body(3, { startAt: '2026-10-08' })).expect(400)
  })

  it('the same submit twice within 3 s → 429 (@Idempotent); 403 without biz.leave.create', async () => {
    const same = body(2)
    await submit('bob', same).expect(201)
    expect((await submit('bob', same).expect(429)).body.code).toBe(Err.TOO_MANY_REQUESTS.code)
    expect((await submit('carol', body()).expect(403)).body.code).toBe(Err.FORBIDDEN.code)
  })
})

describe('WfBusinessHandler leave (a start through /api/wf/instances)', () => {
  const startOf = (who: Who, key: number | string, formValues: object = {}) =>
    startWf(who, { modelKey: 'leave', businessKey: String(key), formValues })

  it('a 3-day request started with forged days = 1 still takes the > 2 days path', async () => {
    const id = await draft({ days: 3 })
    const { body: res } = await startOf('alice', id, { days: 1, leaveKind: 'sick' }).expect(201)
    expect(await instanceRow(res.data.id)).toMatchObject({
      business_key: String(id),
      form_values: { days: 3, leaveKind: 'annual', startAt: '2026-10-08T01:00:00.000Z' },
    })
    expect(await openTasks(res.data.id)).toEqual([{ node_id: 'long', assignee_id: u.carol }])
    expect(await leaveRow(id)).toMatchObject({ state: 'in_review', instance_id: res.data.id })
    // started already → 409, one instance
    await startOf('alice', id, { days: 2 }).expect(409)
    const bound = await ds.query('SELECT id FROM wf_instance WHERE business_key = ?', [String(id)])
    expect(bound).toHaveLength(1)
  })

  it("another user's row, a missing or malformed key → 404; not a draft or bound → 409", async () => {
    await startOf('bob', await draft()).expect(404)
    for (const key of [MISSING, 'abc', '0']) await startOf('alice', key).expect(404)
    await startOf('alice', await draft({ state: 'canceled' })).expect(409)
    await startOf('alice', await draft({ instance_id: MISSING })).expect(409)
  })

  it('an alias of a startable draft’s id is no business key of it: 404, nothing started', async () => {
    const id = await draft()
    const aliases = [`0${id}`, `+${id}`, `${id}.0`, `0x${id.toString(16)}`]
    for (const key of aliases) await startOf('alice', key).expect(404)
    const started = 'SELECT id FROM wf_instance WHERE business_key IN (?)'
    expect(await ds.query(started, [[...aliases, String(id)]])).toEqual([])
    expect(await leaveRow(id)).toMatchObject({ state: 'draft', instance_id: null })
    await startOf('alice', id).expect(201)
  })

  it('locks the row: a start waits for a concurrent writer and then sees its change (409)', async () => {
    const id = await draft()
    const qr = ds.createQueryRunner()
    await qr.startTransaction()
    try {
      await qr.query('SELECT id FROM biz_leave_request WHERE id = ? FOR UPDATE', [id])
      const pending = startOf('alice', id).then((r) => r.status)
      await sleep(400)
      await qr.query("UPDATE biz_leave_request SET state = 'canceled' WHERE id = ?", [id])
      await qr.commitTransaction()
      expect(await pending).toBe(409)
    } finally {
      if (qr.isTransactionActive) await qr.rollbackTransaction()
      await qr.release()
    }
    expect(
      await ds.query('SELECT id FROM wf_instance WHERE business_key = ?', [String(id)]),
    ).toEqual([])
  })

  it('loadFormValues reads current values: an edit committed while it waited is what it sees', async () => {
    const id = await draft({ days: 1 })
    const edit = ds.createQueryRunner()
    await edit.startTransaction()
    try {
      await edit.query('SELECT id FROM biz_leave_request WHERE id = ? FOR UPDATE', [id])
      await edit.query('UPDATE biz_leave_request SET days = 10 WHERE id = ?', [id])
      // a resubmit's transaction: its snapshot is taken before the edit commits
      const read = ds.transaction(async (tx) => {
        await tx.query('SELECT id FROM wf_model WHERE id = ?', [modelId])
        return app.get(LeaveWfHandler).loadFormValues(String(id), tx)
      })
      await sleep(300)
      await edit.commitTransaction()
      expect(await read).toMatchObject({ days: 10 })
    } finally {
      if (edit.isTransactionActive) await edit.rollbackTransaction()
      await edit.release()
    }
  })

  it('onStateChange binds the row and mirrors every instance state (terminated → canceled)', async () => {
    const handler = app.get(LeaveWfHandler)
    const id = await draft()
    const states = {
      running: 'in_review',
      approved: 'approved',
      rejected: 'rejected',
      canceled: 'canceled',
      terminated: 'canceled',
    } as const
    for (const [state, leave] of Object.entries(states)) {
      const inst = { id: MISSING, businessKey: String(id), state } as WfInstanceRow
      await ds.transaction((tx) => handler.onStateChange(inst, tx))
      expect(await leaveRow(id)).toMatchObject({ state: leave, instance_id: MISSING })
    }
  })
})

describe('list', () => {
  const ids = (res: request.Response) => res.body.data.items.map((r: { id: number }) => r.id)

  it("only the caller's own requests, whatever their data scope; 403 without browse", async () => {
    const mine = await add('alice', 2)
    const bobs = await add('bob', 2)
    const list = (who: Who) => call(who, 'get').query({ sort: '-id', pageSize: 100 }).expect(200)
    const alice = await list('alice')
    expect(ids(alice)).toContain(mine.id)
    expect(ids(alice)).not.toContain(bobs.id)
    expect(alice.body.data.items.every((r: { userId: number }) => r.userId === u.alice)).toBe(true)
    // root sees every row of a data-scoped list: this one still shows only its own (none)
    expect(ids(await list('admin'))).toEqual([])
    const kind = await call('alice', 'get').query({ leaveKind: 'sick' }).expect(200)
    expect(kind.body.data.total).toBe(0)
    await call('carol', 'get').expect(403)
  })
})

describe('detail (instance access, sign-in only; see docs/design-notes.md#workflow)', () => {
  it('the owner, its assignees (a delegating owner too) and cc users; admins within their scope', async () => {
    const row = await add('alice', 3) // task of carol (step long), initiator dept `sub`
    const get = (who: Who) => call(who, 'get', `/${row.id}`)
    // carol holds no leave perm: an approver in another dept still sees what she decides on
    for (const who of ['alice', 'carol', 'erin', 'admin'] as const)
      expect((await get(who).expect(200)).body.data).toMatchObject({ id: row.id, days: 3 })
    // bob holds the leave perms but no part in it; frank views instances of dept `other` only;
    // gus's role sees every row but holds no wf.instance.view
    const outsiders = ['bob', 'dave', 'frank', 'gus'] as const
    for (const who of outsiders) await get(who).expect(404)
    // a cc of another instance, a deleted cc, a deleted task: no part in this one
    await addCc((await add('bob', 1)).instanceId, u.dave)
    await addCc(row.instanceId, u.dave, gone)
    await addTask(row.instanceId, 'long', u.frank, gone)
    for (const who of outsiders) await get(who).expect(404)
    await addCc(row.instanceId, u.dave)
    await get('dave').expect(200)
    // a cc of dave opens it to dave only
    for (const who of ['bob', 'frank', 'gus'] as const) await get(who).expect(404)
    // carol delegates the task to bob: she keeps it as its owner
    await ds.query(
      'UPDATE wf_task SET assignee_id = ?, owner_id = ? WHERE instance_id = ? AND assignee_id = ?',
      [u.bob, u.carol, row.instanceId, u.carol],
    )
    await get('carol').expect(200)
    await get('bob').expect(200)
  })

  it('a deleted instance opens its request to no one but the owner', async () => {
    const row = await add('alice', 3) // task of carol; erin views instances of alice's dept
    await ds.query('UPDATE wf_instance SET deleted_at = NOW(3) WHERE id = ?', [row.instanceId])
    for (const who of ['carol', 'erin', 'admin'] as const)
      await call(who, 'get', `/${row.id}`).expect(404)
    await call('alice', 'get', `/${row.id}`).expect(200)
  })

  it('a request with no instance is its owner’s only; unknown or malformed id → 404 / 400', async () => {
    const id = await draft()
    await call('alice', 'get', `/${id}`).expect(200)
    for (const who of ['bob', 'admin'] as const) await call(who, 'get', `/${id}`).expect(404)
    await call('alice', 'get', `/${MISSING}`).expect(404)
    await call('alice', 'get', '/abc').expect(400)
  })
})

describe('edit', () => {
  const put = (who: Who, id: number, patch: object) => call(who, 'put', `/${id}`, patch)

  it('only while a draft or sent back to its owner (a pending begin task), else 409', async () => {
    const row = await add('alice', 3)
    await put('alice', row.id, { days: 4 }).expect(409)
    // alice as the reviewer of a step is not a send-back
    const review = await addTask(row.instanceId, 'long', u.alice)
    await put('alice', row.id, { days: 4 }).expect(409)
    await ds.query("UPDATE wf_task SET state = 'canceled' WHERE id = ?", [review])
    // not a send-back to alice: the begin task of another user, a deleted one, one of another request
    await addTask(row.instanceId, 'begin', u.bob)
    await addTask(row.instanceId, 'begin', u.alice, gone)
    const other = await add('alice', 3)
    await addTask(other.instanceId, 'begin', u.alice)
    await put('alice', row.id, { days: 4 }).expect(409)
    // that other request is sent back to alice, but its instance deleted is not
    await put('alice', other.id, { days: 4 }).expect(200)
    await ds.query('UPDATE wf_instance SET deleted_at = NOW(3) WHERE id = ?', [other.instanceId])
    await put('alice', other.id, { days: 5 }).expect(409)
    const begin = await addTask(row.instanceId, 'begin', u.alice)
    await put('alice', row.id, { days: 4, reason: 'changed' }).expect(200)
    expect(await leaveRow(row.id)).toMatchObject({ days: '4.0', state: 'in_review' })
    // resubmitted: the begin task is done
    await ds.query("UPDATE wf_task SET state = 'approved' WHERE id = ?", [begin])
    await put('alice', row.id, { days: 5 }).expect(409)
    const id = await draft()
    await put('alice', id, { days: 1, leaveKind: 'sick' }).expect(200)
    expect(await leaveRow(id)).toMatchObject({ days: '1.0', state: 'draft' })
  })

  it('server fields in the body are ignored: a sent-back request stays the owner’s, bound, in review', async () => {
    const row = await add('alice', 3)
    await addTask(row.instanceId, 'begin', u.alice)
    const forged = { userId: u.bob, deptId: d.other, state: 'draft', instanceId: null }
    await put('alice', row.id, { days: 4, ...forged }).expect(200)
    expect(await leaveRow(row.id)).toEqual({
      user_id: u.alice,
      dept_id: d.sub,
      state: 'in_review',
      instance_id: row.instanceId,
      days: '4.0',
    })
    // still bound: a second start of it → 409
    await startWf('alice', {
      modelKey: 'leave',
      businessKey: String(row.id),
      formValues: {},
    }).expect(409)
  })

  it('locks the row: an edit racing a resubmit waits for it and then finds the task done (409)', async () => {
    const row = await add('alice', 3)
    const begin = await addTask(row.instanceId, 'begin', u.alice)
    // the resubmit's transaction: the begin task approved, the row read FOR SHARE (loadFormValues)
    const resubmit = ds.createQueryRunner()
    await resubmit.startTransaction()
    try {
      await resubmit.query("UPDATE wf_task SET state = 'approved' WHERE id = ?", [begin])
      await resubmit.query('SELECT id FROM biz_leave_request WHERE id = ? LOCK IN SHARE MODE', [
        row.id,
      ])
      const pending = put('alice', row.id, { days: 9 }).then((r) => r.status)
      await sleep(400)
      await resubmit.commitTransaction()
      expect(await pending).toBe(409)
    } finally {
      if (resubmit.isTransactionActive) await resubmit.rollbackTransaction()
      await resubmit.release()
    }
    expect(await leaveRow(row.id)).toMatchObject({ days: '3.0' })
  })

  it("another user's request or an unknown one → 404; 403 without modify; 400 bad body", async () => {
    const id = await draft()
    await put('bob', id, { days: 1 }).expect(404)
    await put('alice', MISSING, { days: 1 }).expect(404)
    await put('carol', id, { days: 1 }).expect(403)
    await put('alice', id, { days: 0 }).expect(400)
  })
})

it('@ActionLog: submit and edit leave rows with domain biz.leave, their verb and the id', async () => {
  const trace = `${PREFIX}${process.pid}-`
  const res = await submit('alice', body()).set('X-Request-Id', `${trace}c`).expect(201)
  const id = await draft()
  await call('alice', 'put', `/${id}`, { reason: 'logged' })
    .set('X-Request-Id', `${trace}u`)
    .expect(200)
  expect(await logOf(ds, `${trace}c`)).toMatchObject({
    domain: 'biz.leave',
    verb: 'create',
    biz_id: String(res.body.data.id),
    ok: 1,
  })
  expect(await logOf(ds, `${trace}u`)).toMatchObject({ domain: 'biz.leave', verb: 'modify', ok: 1 })
})

it('Swagger documents every route; the leave perms are menu actions of the leave page', async () => {
  const doc = (await request(app.getHttpServer()).get('/api/docs-json').expect(200)).body
  const paths = Object.keys(doc.paths).filter((p) => p.startsWith(URL))
  expect(paths.sort()).toEqual([URL, `${URL}/{id}`])
  expect(Object.keys(doc.paths[`${URL}/{id}`]).sort()).toEqual(['get', 'put'])
  const actions = await ds.query(
    `SELECT a.perms FROM iam_menu a JOIN iam_menu p ON p.id = a.parent_id AND p.deleted_at IS NULL
      WHERE p.route_name = 'biz-leave' AND a.kind = 'action' AND a.deleted_at IS NULL`,
  )
  expect(actions.map((a: { perms: string }) => a.perms).sort()).toEqual(
    Object.values(leavePerms).sort(),
  )
})
